using System;
using System.Collections.Generic;

public class DataFilter
{
    public static List<T> FilterData<T>(List<T>? source, Predicate<T>? condition)
    {
        if (source == null) return new List<T>();
        if (condition == null) return new List<T>(source);

        var result = new List<T>();
        foreach (var item in source)
        {
            if (condition(item))
            {
                result.Add(item);
            }
        }

        return result;
    }

    public static void Main()
    {
        var data = new List<int> { 10, 25, 50, 75, 100 };
        var hasil = FilterData(data, n => n > 40);
        Console.WriteLine(string.Join(", ", hasil));
    }
}
